import pycosat
n = 24
vars_x = [[i*n + v + 1 for v in range(n)] for i in range(n)]
vars_d = [[(n**2) + i*n + d for d in range(1, n)] for i in range(n-1)]
clauses = []
for i in range(n):
    clauses.append(vars_x[i])
    for v1 in range(n):
        for v2 in range(v1+1, n):
            clauses.append([-vars_x[i][v1], -vars_x[i][v2]])
for i in range(n-1):
    for v1 in range(n):
        for v2 in range(v1+1, n):
            d1 = abs(v1 - v2)
            d2 = abs(v2 - v1)  # same
            clauses.append([-vars_x[i][v1], -vars_x[i+1][v2], vars_d[i][d1-1]])
            clauses.append([-vars_x[i][v2], -vars_x[i+1][v1], vars_d[i][d1-1]])
for i in range(n-1):
    clauses.append(vars_d[i])
    for d1 in range(n-1):
        for d2 in range(d1+1, n-1):
            clauses.append([-vars_d[i][d1], -vars_d[i][d2]])
for i in range(n-1):
    for j in range(i+1, n-1):
        for d in range(n-1):
            clauses.append([-vars_d[i][d], -vars_d[j][d]])
clauses.append([vars_x[0][0]])  # x0 = 0
sol = pycosat.solve(clauses, verbose=0)
print(type(sol))
if sol != 'UNSAT':
    perm = [0]*n
    for lit in sol:
        if lit > 0 and lit <= n*n:
            i = (lit-1) // n
            v = (lit-1) % n
            perm[i] = v
    print(perm)
else:
    print(sol)

import itertools
def is_all_interval(perm):
    n = len(perm)
    diffs = [abs(perm[i+1] - perm[i]) for i in range(n-1)]
    return len(set(diffs)) == n-1 and min(diffs) == 1 and max(diffs) == n-1
for p in itertools.permutations(range(1,5)):
    perm = (0,) + p
    if is_all_interval(perm):
        print(perm)
        break
else:
    print("none")

def find_ais(n):
    from collections import deque
    def backtrack(path, used, diff_used):
        if len(path) == n:
            return path
        for next_val in range(n):
            if not used[next_val]:
                diff = abs(path[-1] - next_val)
                if 1 <= diff < n and not diff_used[diff]:
                    used[next_val] = True
                    diff_used[diff] = True
                    res = backtrack(path + [next_val], used, diff_used)
                    if res:
                        return res
                    used[next_val] = False
                    diff_used[diff] = False
        return None
    used = [False] * n
    used[0] = True
    diff_used = [False] * n
    return backtrack([0], used, diff_used)
